export function evidenceCodeLabel(locale: Locale, code: string) {
  return evidenceCodes[locale][code] ?? code.replaceAll("_", " ");
}

export function translate(locale: Locale, key: TranslationKey, values?: Record<string, string | number>) {
  let value: string = dictionaries[locale][key] ?? en[key];
  for (const [name, replacement] of Object.entries(values ?? {})) value = value.replaceAll(`{${name}}`, String(replacement));
  return value;
}
